prompt --application/shared_components/navigation/lists/main_test
begin
wwv_flow_api.create_list(
 p_id=>wwv_flow_api.id(12083143927912881181)
,p_name=>'Main Test'
,p_list_type=>'SQL_QUERY'
,p_list_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with t as',
' (select sum(case',
'               when ITEM_SEQ  is not null then',
'                1',
'               else',
'                0',
'             end) Cancelled,',
'         ',
'         sum(case',
'               when MOD_REQUEST_ISN is not null then',
'                1',
'               else',
'                0',
'             end) Available,',
'         sum(case',
'               when MOD_REQUEST_ISN is not null and MFST_DT is null then',
'                1',
'               else',
'                0',
'             end) Booked,',
'         sum(case',
'               when MOD_REQUEST_ISN is not null and MFST_DT is not null then',
'                1',
'               else',
'                0',
'             end) arrived,',
'         sum(case',
'               when MOD_REQUEST_ISN is not null and BL_SEQ is not null and',
'                    MFST_NBR is not null and MFST_TYPE is not null then',
'                1',
'               else',
'                0',
'             end) completed',
'from COC_MOD_REQUESTS ',
'  )',
'select null as lvl,',
'       label as label,',
'       ''javascript:apex.item(''''P17_SUMM_FITER'''').setValue(''''''||ord||'''''');''  as target,',
'       null as attribute1,',
'       null as attribute2,',
'       null as attribute3,',
'       null as attribute4,',
'      value as attribute5,',
'       style as attribute6,',
'       style as attribute7 from   (select value, label, style  , ord from (',
'select 6 ord , 0 value, '' '' label , '' '' style ',
'  from t',
'  union',
unistr('  select 5 ord , Cancelled value, ''\0637\0644\0628\0627\062A \0627\0644\0623\0635\0646\0627\0641 \0627\0644\063A\064A\0631 \0645\0646\0641\0630\0647'' label , '''' style'),
'  from t',
'union',
unistr('select 1 ,  available, ''\0625\062C\0645\0627\0644\064A \0639\062F\062F \0627\0644\0637\0644\0628\0627\062A'' , ''style="background-color:green"'' style'),
'  from t',
'union',
unistr('select 2, booked, ''\0639\062F\062F \0627\0644\0637\0644\0628\0627\062A \0627\0644\063A\064A\0631 \0645\0646\0641\0630\0647'' , ''style="background-color:red"'' style'),
'  from t',
'union',
unistr('select 3, arrived, ''\0637\0644\0628\0627\062A \0627\0644\0645\0646\0627\0641\064A\0633\062A \0627\0644\063A\064A\0631 \0645\0646\0641\0630\0647'' , ''style="background-color:#f0ad4e"'' style'),
'  from t',
'union',
unistr('select 4, Completed, ''\0637\0644\0628\0627\062A \0627\0644\0628\0648\0627\0644\0635 \0627\0644\063A\064A\0631 \0645\0646\0641\0630\0647''  , ''style="background-color:#5c7fe1"'' style'),
'from t',
') where ord <> 6',
'order by ord)'))
,p_list_status=>'PUBLIC'
);
end;
