prompt --application/shared_components/navigation/lists/requests_summry
begin
wwv_flow_api.create_list(
 p_id=>wwv_flow_api.id(12083399151807257858)
,p_name=>'Requests SUMMRY'
,p_list_type=>'SQL_QUERY'
,p_list_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with t as',
' (select sum(case',
'               when DCLTN_ISN  is not null then',
'                1',
'               else',
'                0',
'             end) Cancelled,',
'         ',
'         sum(case',
'               when DCLTN_STA_CD is not null then',
'                1',
'               else',
'                0',
'             end) Available,',
'         sum(case',
'               when DCLTN_STA_CD is not null  then',
'                1',
'               else',
'                0',
'             end) Booked,',
'         sum(case',
'               when DCLTN_STA_CD is not null then',
'                1',
'               else',
'                0',
'             end) arrived,',
'         sum(case',
'               when DCLTN_STA_CD is not null then',
'                1',
'               else',
'                0',
'             end) completed',
'from DECLARATIONS',
' where rownum<=2',
'  )',
'select null as lvl,',
'       label as label,',
'       ''javascript:apex.item(''''P1_SUMM_FITER'''').setValue(''''''||ord||'''''');''  as target,',
'       null as attribute1,',
'       null as attribute2,',
'       null as attribute3,',
'       null as attribute4,',
'      value as attribute5,',
'       style as attribute6,',
'       style as attribute7 from   (select value, label, NULL style  , ord from (',
unistr('  select 1 ord , Cancelled value, ''\0627\0644\062A\0646\0628\0647\0627\062A'' label , '''' style'),
'  from t',
'union',
unistr('select 2 ,  available, ''\0627\0644\0627\0634\062A\0628\0627\0647'' , ''style="background-color:green"'' style'),
'  from t',
'  union',
unistr('select 3 ,  available, ''\0627\0644\0645\0631\0641\0648\0636\0629'' , ''style="background-color:green"'' style'),
'  from t',
'   union',
unistr('select 4 ,  available, ''\0627\0644\0627\0634\062A\0628\0627\0647'' , ''style="background-color:green"'' style'),
'  from t',
'',
')',
'order by ord)'))
,p_list_status=>'PUBLIC'
);
end;
