prompt --application/shared_components/navigation/lists/page_functions
begin
wwv_flow_api.create_list(
 p_id=>wwv_flow_api.id(73515118111876811433)
,p_name=>'Page Functions'
,p_list_type=>'SQL_QUERY'
,p_list_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1 LVL,',
'F.LBL LABEL,',
'case',
'when F.HAS_EVENT > 0 then',
'''javascript:apex.theme.closeRegion(''''FUNCS'''');apex.event.trigger(document,'''''' || replace(F.EVENT_NAME, '''''''', '''') || '''''',{url:'''''' ||',
'case when F.PAGE_ID is not null then',
'apex_page.get_url(p_page => F.PAGE_ID,',
'p_clear_cache => ''0,'' || F.PAGE_ID,',
'p_items => case when F.HAS_MODULE = 1 then ''P'' || F.PAGE_ID || ''_MODULE_ID'' end,',
'p_values => case when F.HAS_MODULE = 1 then to_char(F.SYSOBJ_ID) end)',
'end || ''''''});''',
'when F.PAGE_ID is not null then',
'apex_page.get_url(p_page => F.PAGE_ID,',
'p_clear_cache => ''0,'' || F.PAGE_ID,',
'p_items => case when F.HAS_MODULE = 1 then ''P'' || F.PAGE_ID || ''_MODULE_ID'' end,',
'p_values => case when F.HAS_MODULE = 1 then to_char(F.SYSOBJ_ID) end)',
'else',
unistr('''javascript:apex.message.alert(''''\0627\0644\0648\0638\064A\0641\0629 \00AB'' || replace(replace(F.LBL, '''''''', ''''), ''"'', '''') ||'),
unistr('''\00BB \0644\0645 \064A\062A\0645 \062A\062D\0648\064A\0644\0647\0627 \0625\0644\0649 APEX \0628\0639\062F'''');'''),
'end TARGET,',
'null IS_CURRENT,',
'''fa-angle-left'' IMAGE,',
'null IMAGE_ATTRIBUTE,',
'null IMAGE_ALT_ATTRIBUTE',
'from (select X.SYSOBJ_ID, X.LBL, X.EVENT_NAME,',
'(select count(*) from APEX_APPLICATION_PAGE_DA D',
'where D.APPLICATION_ID = :APP_ID and D.PAGE_ID = :APP_PAGE_ID',
'and upper(D.WHEN_EVENT_CUSTOM_NAME) = upper(X.EVENT_NAME)) HAS_EVENT,',
'(select min(P.PAGE_ID) from APEX_APPLICATION_PAGES P',
'where P.APPLICATION_ID = :APP_ID and P.PAGE_NAME = X.FILE_NAME) PAGE_ID,',
'(select count(*) from APEX_APPLICATION_PAGE_ITEMS I, APEX_APPLICATION_PAGES P',
'where P.APPLICATION_ID = :APP_ID and P.PAGE_NAME = X.FILE_NAME',
'and I.APPLICATION_ID = P.APPLICATION_ID and I.PAGE_ID = P.PAGE_ID',
'and I.ITEM_NAME = ''P'' || P.PAGE_ID || ''_MODULE_ID'') HAS_MODULE',
'from (select distinct FUN.SYSOBJ_ID, FUN.SYS_ANAME LBL,',
'upper(regexp_replace(FUN.SYS_OS_FILE_NAME, ''\..*$'', '''')) FILE_NAME,',
'FUN.SYS_OS_FILE_NAME EVENT_NAME',
'from SC_SYSTEM_OBJECTS FUN, SC_SYSTEM_OBJECTS SCREN, SC_SYSOBJ_ROLE_PRIVS SOF',
'where FUN.SYS_STATUS = 1',
'and FUN.MAINSYSOBJ_ID = SCREN.SYSOBJ_ID',
'and FUN.SYSOBJ_ID = SOF.SYSOBJ_ID',
'and upper(regexp_replace(SCREN.SYS_OS_FILE_NAME, ''\..*$'', '''')) =',
'(select P.PAGE_NAME from APEX_APPLICATION_PAGES P',
'where P.APPLICATION_ID = :APP_ID and P.PAGE_ID = :APP_PAGE_ID)',
'and SOF.ROLE_ID in (select UR.ROLE_ID from SC_USER_ROLES UR',
'where UR.USER_ID = :SSO_APP_USER and UR.PORT_CD = :P_CURR_PORT_CD and UR.UR_ACTIVE = 1',
'union',
'select GR.ROLE_ID from SC_GROUP_ROLES GR, SC_USER_GROUPS UG',
'where UG.PORT_CD = :P_CURR_PORT_CD and UG.USER_ID = :SSO_APP_USER',
'and GR.GROUP_ID = UG.GROUP_ID and GR.GR_ACTIVE = 1',
'minus',
'select UER.ROLE_ID from SC_USER_EXCLUDED_ROLES UER',
'where UER.USER_ID = :SSO_APP_USER and UER.PORT_CD = :P_CURR_PORT_CD and UER.UER_ACTIVE = 1)',
'and (not exists (select 1 from APEX_APPLICATION_PAGE_ITEMS I',
'where I.APPLICATION_ID = :APP_ID and I.PAGE_ID = :APP_PAGE_ID',
'and I.ITEM_NAME = ''P'' || :APP_PAGE_ID || ''_ADJ_FUNS'')',
'or upper(trim(FUN.SYS_OS_FILE_NAME)) in',
'(select upper(trim(column_value))',
'from table(apex_string.split(v(''P'' || :APP_PAGE_ID || ''_ADJ_FUNS''), '',''))))) X) F',
'order by F.LBL'))
,p_list_status=>'PUBLIC'
);
end;
