prompt --application/shared_components/logic/application_processes/after_auth
begin
wwv_flow_api.create_flow_process(
 p_id=>wwv_flow_api.id(12085469569020088375)
,p_process_sequence=>1
,p_process_point=>'AFTER_LOGIN'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'After Auth'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
':SSO_APP_USER := GENERAL_UTILITY.ZATCA_SSO(:APP_USER);',
'SELECT VAR_VALUE ',
'INTO :P_CURR_PORT_CD ',
'FROM SC_PORT_SETTING',
'WHERE  VAR_NAME =''PORT_CD'';',
'SELECT p.PORT_NAME , port_type  INTO :PORT_NAME , :P_GLOBAL_PORT_TYPE',
'FROM sd_ports p',
'WHERE PORT_CD = :P_CURR_PORT_CD;',
' BEGIN',
'     SELECT ',
'     A.USR_ANAME,',
'         USR_TYPE_CD,',
'         CLASS_CD,',
'         JOB_ID',
'     INTO   ',
'     :V_USR_NAME,',
'         :V_USR_TYPE,',
'         :V_CLASS_CD,',
'         :V_JOB_ID',
'     FROM SC_USERS A',
'     WHERE UPPER(A.USER_ID) =UPPER(:SSO_APP_USER)',
'     AND A.PORT_CD = :P_CURR_PORT_CD;',
' exception when others then null;',
' end;',
'',
':P_GLOBAL_V_WS_ID :=''APEX-WS'';    ',
':P_CLASS_CD := :V_CLASS_CD;',
'select max(port_type) into :P_PORT_TYPE from sd_ports ',
'where port_cd = :P_CURR_PORT_CD;',
unistr(':DOCNAME := ''\0627\0644\0645\0633\062A\0646\062F'';'),
':G_UP_MAIN := 999;',
':G_FULL_PATH_NAME := ''XXX'';',
':G_FULL_PATH_NAME_LNK := ''NIL'';',
':G_CLEAR_SETTION := 1 ;',
'',
'IF  :P_CURR_PORT_CD =53 AND :P_GLOBAL_PORT_TYPE =1  THEN ',
'    :P_GLOBAL_PORT_TYPE :=3 ;',
'    :P_PORT_TYPE        :=3 ;',
'END IF;',
':DMC_BASED_URL := ''https://weblogic_dmc_cont4.zatca.gov.sa''  ;',
'',
' SELECT RV_LOW_VALUE',
' INTO :CURRENT_DMC_SERVER FROM CG_REF_CODES WHERE RV_DOMAIN=''DMC_SERVER'';'))
,p_process_clob_language=>'PLSQL'
);
end;
/
prompt --application/shared_components/logic/application_processes/screen_entry_reset
begin
wwv_flow_api.create_flow_process(
 p_id=>wwv_flow_api.id(73505118111877798477)
,p_process_sequence=>1
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SCREEN ENTRY RESET'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_base number := case when :APP_PAGE_ID >= 100000 then trunc(:APP_PAGE_ID / 100) else :APP_PAGE_ID end;',
'begin',
unistr('    -- \0623\0648\0644 \062F\062E\0648\0644 \0644\0644\0634\0627\0634\0629 (\0645\0646 \0627\0644\0645\0646\064A\0648 \0623\0648 \0645\0646 \0634\0627\0634\0629 \062A\0627\0646\064A\0629): \062A\0641\062A\062D \0641\0627\0636\064A\0629'),
unistr('    -- \0627\0644\0634\0627\0634\0629 \0646\0641\0633\0647\0627 \0648\0634\0627\0634\0629 \0627\0644\0628\062D\062B \0628\062A\0627\0639\062A\0647\0627 (+01) \0628\064A\062D\0627\0641\0638\0648\0627 \0639\0644\0649 \0627\0644\0633\062C\0644 \0627\0644\0645\0641\062A\0648\062D'),
'    if :APP_PAGE_ID not in (0, 9999)',
'       and nvl(:G_LAST_PAGE, -1) not in (l_base, l_base * 100 + 1) then',
'        :P0_PAGE_PK := null;',
'        for r in (select i.item_name',
'                    from apex_application_page_items i',
'                   where i.application_id = :APP_ID',
'                     and i.page_id        = :APP_PAGE_ID',
'                     and i.item_name     <> ''P'' || :APP_PAGE_ID || ''_MODULE_ID'')',
'        loop',
'            apex_util.set_session_state(r.item_name, null);',
'        end loop;',
'    end if;',
'    :G_LAST_PAGE := :APP_PAGE_ID;',
'end;'))
,p_process_clob_language=>'PLSQL'
);
end;
/
prompt --application/shared_components/logic/application_processes/set_theme_style
begin
wwv_flow_api.create_flow_process(
 p_id=>wwv_flow_api.id(73505118111877798470)
,p_process_sequence=>1
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SET_THEME_STYLE'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_id number;',
'begin',
'    select s.theme_style_id',
'      into l_id',
'      from apex_application_theme_styles s',
'     where s.application_id = :APP_ID',
'       and s.theme_number   = 42',
'       and s.name           = apex_application.g_x01;',
'    apex_theme.set_user_style(p_application_id => :APP_ID, p_user => :APP_USER, p_theme_number => 42, p_id => l_id);',
'    apex_theme.set_session_style(p_theme_number => 42, p_name => apex_application.g_x01);',
'    htp.p(''OK'');',
'exception',
'    when no_data_found then htp.p(''NOT_FOUND'');',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
);
end;
/
