prompt --application/shared_components/automations/solvecanddate
begin
wwv_flow_api.create_automation(
 p_id=>wwv_flow_api.id(11459336739888498290)
,p_name=>'SOLVECANDDATE'
,p_static_id=>'solvecanddate'
,p_trigger_type=>'POLLING'
,p_polling_interval=>'FREQ=MINUTELY;INTERVAL=15'
,p_polling_status=>'DISABLED'
,p_result_type=>'ALWAYS'
,p_use_local_sync_table=>false
,p_include_rowid_column=>false
,p_commit_each_row=>false
,p_error_handling_type=>'IGNORE'
);
wwv_flow_api.create_automation_action(
 p_id=>wwv_flow_api.id(11459337053347498318)
,p_automation_id=>wwv_flow_api.id(11459336739888498290)
,p_name=>'New Action'
,p_execution_sequence=>10
,p_action_type=>'NATIVE_PLSQL'
,p_action_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   v_pega_status   NUMBER;',
'   v_AEO_RSN_ISN   NUMBER;',
'   v_recp_flag     NUMBER;',
'   V_TIME          VARCHAR2 (200);',
'   v_diff_flag     NUMBER;',
'   V_COUNT         NUMBER;',
'BEGIN',
'   FOR I IN (SELECT *',
'               FROM DECLARATIONS',
'              WHERE DCLTN_TYPE_CD = 7 AND TO_CHAR (DCLTN_DT, ''YYYY'') = TO_CHAR(HIJDATE_DB.Cur_Hij_Date,''YYYY'')   )',
'   LOOP',
'      SELECT COUNT (*)',
'        INTO V_COUNT',
'        FROM MANUAL_INSPCT_CANDIDATE',
'       WHERE     CANDIDATE_STATUS IN (0, 1)',
'             AND DCLTN_ISN = I.DCLTN_ISN',
'             AND PORT_CD = I.PORT_CD;',
'',
'      IF V_COUNT > 0',
'      THEN',
'         -- raise_application_error(-20001,V_COUNT);',
'         SELECT pega_status, AEO_RSN_ISN, NVL (recp_flag, 0)',
'           INTO v_pega_status, v_AEO_RSN_ISN, v_recp_flag',
'           FROM declarations',
'          WHERE port_cd = I.PORT_CD AND dcltn_isn = I.DCLTN_ISN;',
'',
'         V_TIME :=',
'               TO_CHAR (SYSDATE - 3 / 24, ''yyyymmdd'')',
'            || ''T''',
'            || TO_CHAR (SYSDATE - 3 / 24, ''hhmiss'')',
'            || ''.000 GMT'';',
'         v_diff_flag := dcltn.impr_duty_diff (I.PORT_CD, I.DCLTN_ISN, 1);',
'',
'         -- IF v_recp_flag = 1  THEN',
'         edi_trg.database_xml_create (4,',
'                                      ''PegaConsumeService.DecStages'',',
'                                      ''DecCreateNewCaseInICC'',',
'                                      ''PGA'',',
'                                      ''DECLARATIONS'',',
'                                      I.PORT_CD,',
'                                      I.DCLTN_ISN,',
'                                      v_AEO_RSN_ISN,',
'                                      V_TIME);',
'         -- END IF;',
'         COMMIT;',
'      END IF;',
'   END LOOP;',
'END;'))
,p_action_clob_language=>'PLSQL'
,p_location=>'LOCAL'
,p_stop_execution_on_error=>true
);
end;
/
prompt --application/shared_components/security/authentications/jwt
begin
wwv_flow_api.create_authentication(
 p_id=>wwv_flow_api.id(11575710538323461043)
,p_name=>' JWT'
,p_scheme_type=>'NATIVE_CUSTOM'
,p_attribute_01=>'TOKEN_SENTRY_FUNCTION'
,p_attribute_05=>'N'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'FUNCTION TOKEN_SENTRY_FUNCTION',
'RETURN BOOLEAN',
'IS',
'    l_query_string VARCHAR2(4000) := SYS.OWA_UTIL.GET_CGI_ENV(''QUERY_STRING'');',
'    l_token        VARCHAR2(4000);',
'    l_name     VARCHAR2(4000);',
'    l_username     VARCHAR2(200);',
'    l_session      NUMBER;',
'BEGIN',
'       -- insert into yaghi_TEST values(''1. l_query_string >>>''||l_query_string);',
'',
'    -- URL for testing http://localhost:8080/ords/f?p=116:1&x01=TOKEN:ABC',
'    -- don''t do anything if user is already logged on',
'    IF APEX_APPLICATION.G_USER <> ''nobody''',
'    THEN',
'        RETURN TRUE;',
'    END IF;',
'     --   insert into yaghi_TEST values(''2. l_query_string >>>''||l_query_string);',
'',
'    -- grab the token value',
'    l_token := REPLACE(REGEXP_SUBSTR  (  l_query_string, ''&token=([^&]+)'',1,1,''i''),''&token='' ,'''' );',
'    l_name := REPLACE(REGEXP_SUBSTR  (  l_query_string, ''&username=([^&]+)'',1,1,''i''),''&username='' ,'''');',
'    -- QUERY_STRING contains something like p=116:1&x01=TOKEN:ABC',
'       -- insert into yaghi_TEST values(''l_token in >>>''||l_token);',
'   -- insert into yaghi_TEST values(''l_name in >>>''||l_name);',
'    ',
'    IF l_token IS NOT NULL',
'    THEN',
'        -- test token, see if it is',
'        --           1) found in token table',
'        --           2) unused',
'        --           3) still valid (max age x seconds)',
'            insert into RAG_TOKEN (USERNAME, TOKEN_STRING, USED_AT)',
'            select UPPER(l_name), l_token,SYSDATE',
'            from dual  where not exists (select 1 from RAG_TOKEN where UPPER(USERNAME) = UPPER(l_name));',
'        UPDATE RAG_TOKEN',
'           SET USED_AT      = SYSDATE, TOKEN_STRING=l_token',
'         WHERE UPPER(USERNAME) = UPPER(l_name);',
'         ',
'        SELECT USERNAME',
'          INTO l_username',
'          FROM RAG_TOKEN',
'         WHERE TOKEN_STRING  = l_token',
'--           AND USED_AT      IS NULL',
'--           AND CREATED_AT   < SYSDATE-1/24/60',
'        ;',
'',
'        -- mark token as used at current time',
'        /*UPDATE RAG_TOKEN',
'           SET USED_AT      = SYSDATE',
'         WHERE TOKEN_STRING = l_token',
'        ;*/',
'',
'        -- is there already a session?',
'        l_session := APEX_CUSTOM_AUTH.GET_SESSION_ID_FROM_COOKIE;',
'',
'        IF l_session IS NOT NULL',
'        THEN',
'            -- test if the session is still valid and get a new session id, if not valid',
'            IF NOT APEX_CUSTOM_AUTH.IS_SESSION_VALID',
'            THEN',
'                l_session := APEX_CUSTOM_AUTH.GET_NEXT_SESSION_ID;',
'            END IF;',
'',
'        ELSE',
'            -- no session in cookie found, get a new session id',
'            l_session := APEX_CUSTOM_AUTH.GET_NEXT_SESSION_ID;',
'        END IF;',
'',
'        -- initialize the session',
'        APEX_CUSTOM_AUTH.DEFINE_USER_SESSION (',
'            l_username,',
'            l_session);',
'',
'        RETURN TRUE;',
'    END IF;',
'',
'    RETURN FALSE;',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN RETURN FALSE;',
'END;',
'',
''))
,p_invalid_session_type=>'URL'
,p_invalid_session_url=>'https://esso.zatca.gov.sa/apex/login'
,p_cookie_name=>'&WORKSPACE_COOKIE.'
,p_use_secure_cookie_yn=>'N'
,p_ras_mode=>0
);
end;
/
