prompt --application/shared_components/plugins/region_type/apexbcreader
begin
wwv_flow_api.create_plugin(
 p_id=>wwv_flow_api.id(26987325013137139598)
,p_plugin_type=>'REGION TYPE'
,p_name=>'APEXBCREADER'
,p_display_name=>'BarcodeReader'
,p_supported_ui_types=>'DESKTOP:JQM_SMARTPHONE'
,p_image_prefix => nvl(wwv_flow_application_install.get_static_plugin_file_prefix('REGION TYPE','APEXBCREADER'),'')
,p_javascript_file_urls=>wwv_flow_string.join(wwv_flow_t_varchar2(
'#PLUGIN_FILES#apexbcr/decoderworker.js',
'#PLUGIN_FILES#apexbcr/exif.js',
'#PLUGIN_FILES#apexbcr/barcodereader.js',
'#PLUGIN_FILES#apexbcr/apexbcreader.js'))
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function addBarCodeReaderRegion (',
'    p_region              in apex_plugin.t_region,',
'    p_plugin              in apex_plugin.t_plugin,',
'    p_is_printer_friendly in boolean )',
'return apex_plugin.t_region_render_result',
'is',
'    -- constants',
'    c_video_id      varchar2(100) := ''bcreaderVideo'';',
'    c_canvas_id     varchar2(100) := ''bcreaderVideoCanvas'';',
'    -- attributes',
'    l_decodeFormats varchar2(32676) := p_region.attribute_01;',
'    l_facingMode    varchar2(32676) := p_region.attribute_02;',
'    --',
'    l_jscode        varchar2(32676) := '''';',
'    l_jsarray       varchar2(32676) := '''';',
'    -- dummy result',
'    l_result      apex_plugin.t_region_render_result;',
'begin',
'    -- render the html',
'    htp.p(''<canvas id="''||c_canvas_id||''" class="apex-barcode-reg"> <video id ="''||c_video_id||''"/></canvas>'');',
'    -- check custom attributes',
'    if l_facingMode is not null',
'    then',
'        -- set camera facingMode',
'        l_jscode := l_jscode || ''ApExBCReader.SetFacingMode(''''''||l_facingMode||'''''');''; ',
'    end if;',
'    if l_decodeFormats is not null',
'    then',
'        -- set the configured formats',
'        -- construct js array',
'        l_jsarray := ''["'' || replace(l_decodeFormats,'':'',''", "'') || ''"]'';',
'        l_jscode := l_jscode || ''ApExBCReader.SetDecodeFormats(''''''||l_jsarray||'''''');''; ',
'    end if;',
'    -- init javascript ApExBCReader',
'    apex_debug.info(''custom js : ''||l_jscode);',
'    apex_javascript.add_inline_code( p_code => l_jscode || ''ApExBCReader.Init();''',
'                                   , p_key  => ''apexbcr_plugin'' );',
'    -- ',
'    return l_result;',
'end addBarCodeReaderRegion;'))
,p_api_version=>2
,p_render_function=>'addBarCodeReaderRegion'
,p_substitute_attributes=>true
,p_reference_id=>5396381244611245676
,p_subscribe_plugin_settings=>true
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'The PlugIn can be used in APEX as a region. it uses the html5 <video> capabilties for the camera. ',
'The barcode reader will analyze the image and the value of barcode is read with the event ''apexbcreader''. ',
'You can use a Dynamic Action on this event to process this value further.'))
,p_version_identifier=>'1.0'
,p_files_version=>17
);
