'begin',
unistr('  -- \0634\0627\0634\0629 \0627\0644\0628\062D\062B \0645\0648\062C\0648\062F\0629\061F (\0631\0642\0645 \0627\0644\0634\0627\0634\0629 + 01)'),
'  select count(*) into l_cnt',
'    from apex_application_pages',
'   where application_id = :APP_ID',
'     and page_id        = l_page;',
'  if l_cnt = 0 then',
'    return null;',
'  end if;',
