wwv_flow_api.create_page_da_action(
 p_id=>wwv_flow_api.id(81908773946347291813)
,p_event_id=>wwv_flow_api.id(81908773946347291812)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('// APX_ASK INIT: \0643\0648\062F DA \0627\0644\0640 Page Load \0639\0644\0649 Page 0 (\0627\0644\0633\062A\0627\0646\062F\0631\062F STD-1.0.3\060C DEC-009).'),
unistr('// \0628\064A\062A\062D\0637 \0641\064A \0627\0644\0640 DA \0646\0641\0633\0647\0627 \0645\0634 \0643\0640 Static File (\0633\062A\0627\0646\062F\0631\062F 26)\060C \0648\0627\0644\0645\0644\0641 \062F\0647 \0645\0631\062C\0639\0647.'),
unistr('// ASK_DLG: Inline Dialog \0641\064A\0647 ASK_MSG \0648\0627\0644\0623\0632\0631\0627\0631 ASK_B1 / ASK_B2 / ASK_B3.'),
'window.apxAsk = (function () {',
'  var retryFn = null;',
'',
'  function answerItem() {',
'    return ''P'' + $v(''pFlowStepId'') + ''_F_ANSWER'';',
'  }',
'',
'  function clicked(n) {',
'    var item = answerItem(), cur = $v(item), f = retryFn;',
'    retryFn = null;',
'    $s(item, cur ? cur + '','' + n : String(n));',
'    apex.theme.closeRegion(''ASK_DLG'');',
'    if (f) f();',
'  }',
'',
unistr('  // true: \0648\0642\0641 \0627\0644\0640 DA (\0633\0624\0627\0644 \0627\062A\0639\0631\0636 \0623\0648 ABORT). false: \0643\0645\0651\0644 \0627\0644\0637\0631\064A\0642 \0627\0644\0639\0627\062F\064A.'),
'  function handle(res, retry) {',
'    if (!res) return false;',
'    if (res.indexOf(''CONFIRM:'') === 0) {',
'      var q = JSON.parse(res.substring(8));',
'      $(''#ASK_MSG'').text(q.msg);',
'      [1, 2, 3].forEach(function (i) {',
'        var b = $(''#ASK_B'' + i), lbl = q[''b'' + i];',
'        if (lbl) { b.text(lbl).show(); } else { b.hide(); }',
'      });',
'      retryFn = retry;',
'      apex.theme.openRegion(''ASK_DLG'');',
unistr('      // \0645\0641\064A\0634 \0642\0641\0644 \0645\0646 \063A\064A\0631 \0627\062E\062A\064A\0627\0631: \0644\0627 X \0648\0644\0627 Esc\060C \0627\0644\0645\0633\062A\062E\062F\0645 \0644\0627\0632\0645 \064A\0636\063A\0637 \0632\0631\0627\0631'),
'      $(''#ASK_DLG'').dialog(''option'', ''closeOnEscape'', false)',
'        .closest(''.ui-dialog'').find(''.ui-dialog-titlebar-close'').hide();',
'      return true;',
'    }',
'    if (res.indexOf(''UI:'') === 0) {',
'      apex.navigation.redirect(JSON.parse(res.substring(3)).url);',
'      return false;',
'    }',
'    return res === ''ABORT'';',
'  }',
'',
'  [1, 2, 3].forEach(function (i) {',
'    $(''#ASK_B'' + i).on(''click'', function () { clicked(i); });',
'  });',
'',
'  return { handle: handle };',
'})();'))
);
