,p_execute_on_page_init=>'Y'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'(function (apex, $) {',
'"use strict";',
unistr('var ON = /^(\0641\0639\0627\0644|\0641\0639\0627\0644\0629|\0646\0634\0637|\0645\062A\0635\0644|\0645\0641\0639\0644)$/;'),
unistr('var OFF = /^(\063A\064A\0631 \0641\0639\0627\0644|\063A\064A\0631 \0641\0639\0627\0644\0629|\0645\0648\0642\0648\0641|\0645\0644\063A\064A|\0645\0644\063A\0649|\063A\064A\0631 \0645\062A\0635\0644|\063A\064A\0631 \0645\0641\0639\0644|\0645\0646\062A\0647\064A)$/;'),
unistr('var WARN = /^(\0625\062C\0627\0632\0629|\0627\062C\0627\0632\0629|\0645\0639\0644\0642|\0642\064A\062F \0627\0644\0645\0631\0627\062C\0639\0629)$/;'),
'function paint(root) {',
'var cells = root.querySelectorAll(".a-GV-cell");',
'for (var i = 0; i < cells.length; i++) {',
'var c = cells[i], t = c.textContent;',
'if (!t || t.length > 30 || c.firstElementChild) continue;',
't = t.replace(/\s+/g, " ").trim();',
'var k = ON.test(t) ? "on" : OFF.test(t) ? "off" : WARN.test(t) ? "warn" : null;',
'if (!k) continue;',
'c.innerHTML = ''<span class="cg-pill cg-pill--'' + k + ''"></span>'';',
'c.firstChild.textContent = t;',
'}',
'}',
'function fit(ig) {',
'try {',
'var v, g;',
'try { v = apex.region(ig.id.replace(/_ig$/, "")).call("getViews", "grid"); } catch (e) {}',
'g = v && v.view$ ? v.view$ : $(ig).find(".a-GV").first();',
'if (!g.length || !g.grid) return;',
'var by = {}, ch = 0, B = g.find(".a-GV-bdy table");',
'g.grid("getColumns").forEach(function (k) {',
'if (k.property && !k.hidden && !/^APEX\$/.test(k.property))',
'by[$.trim(String(k.heading || "").replace(/<[^>]*>/g, ""))] = k;',
'});',
'g.find(".a-GV-hdr table").each(function (t) {',
'var b = B[t];',
'$(this).find("tr").last().children().each(function (j) {',
'var k = by[$.trim($(this).find(".a-GV-headerLabel").text() || $(this).text())];',
'if (!k) return;',
'var d = this.scrollWidth - this.clientWidth, th = this;',
'if (b) $(b).find("tr").slice(0, 300).each(function () {',
'var td = this.children[j];',
'if (td) d = Math.max(d, td.scrollWidth - td.clientWidth);',
'});',
'if (d > 1) { k.width = Math.min(450, (k.width || th.offsetWidth) + d + 8); ch = 1; }',
'});',
'});',
'if (ch && (g[0].cgN = (g[0].cgN || 0) + 1) < 12) g.grid("refreshColumns").grid("refresh");',
'} catch (e) { if (window.console) console.warn("cg-fit", e); }',
'}',
'function watch(ig) {',
'if (ig.cgWatched) return;',
'ig.cgWatched = true;',
'var q = 0;',
'paint(ig);',
'fit(ig);',
'new MutationObserver(function () {',
'if (!q) q = setTimeout(function () { q = 0; paint(ig); fit(ig); }, 120);',
'}).observe(ig, { childList: true, subtree: true });',
'}',
'var HB;',
'function hpos(i) {',
'var w = $(".bootstrap-datetimepicker-widget").last();',
'if (!w.length) return;',
'var r = i.getBoundingClientRect(), h = w.outerHeight(), ww = w.outerWidth(), t = r.bottom + 2;',
'if (t + h > innerHeight && r.top > h) t = r.top - h - 2;',
'w.css({ position: "fixed", top: t, bottom: "auto", left: Math.max(4, Math.min(r.right - ww, innerWidth - ww - 4)), right: "auto", zIndex: 9000 });',
'}',
'$(document).on("focusin", "input.hijri-date-default", function () {',
'var i = this, $i = $(i), p = $i.data("HijriDatePicker");',
'if (!$.fn.hijriDatePicker) return;',
'if (!p) {',
'$i.hijriDatePicker({ hijri: true, showSwitcher: false }).on("dp.change", function () { apex.event.trigger(i, "change"); });',
'p = $i.data("HijriDatePicker");',
'}',
'if (!i.cgHij) {',
'i.cgHij = 1;',
'HB = HB || $(''<div class="cg-hij" style="position:relative;height:0"></div>'').appendTo("body");',
'$i.on("dp.show dp.update", function () { hpos(i); });',
'p.widgetParent(HB);',
'}',
'p.show();',
'hpos(i);',
'});',
'function all() { $(".a-IG").each(function () { watch(this); }); }',
'$(all);',
'$(document).on("apexreadyend interactivegridviewchange apexafterrefresh", all);',
'})(apex, apex.jQuery);'))
);
