wwv_flow_api.create_page_plug(
 p_id=>wwv_flow_api.id(460632672718563860)
,p_plug_name=>unistr('\0627\0644\0645\0633\062A\0648\0631\062F\0648\0646 \0627\0644\0645\062E\062A\0627\0631\0648\0646')
,p_region_name=>'CTR_BLK'
,p_region_css_classes=>'cg-card cg-grid'
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding'
,p_plug_template=>wwv_flow_api.id(12082545948334433538)
,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- CTR_BLK.WHEN-NEW-BLOCK-INSTANCE: one row per importer number of LICE_NO, with the name of the importer of the port',
'-- (CALLING_PARAMETERS.LICE_NO.WHEN-VALIDATE-ITEM: port NVL(P_PORT_CD, PARAMETER.P_CURR_PORT_CD), message if not found)',
'SELECT l.seq, l.p_agr_nbr,',
unistr('       NVL(i.arbc_impr_name, ''\0647\0630\0627 \0627\0644\0645\0633\062A\0648\0631\062F \063A\064A\0631 \0645\0648\062C\0648\062F'') AS p_agr_desc'),
'  FROM (SELECT LEVEL AS seq,',
'               TO_NUMBER(REGEXP_SUBSTR(REGEXP_REPLACE(:P2110_LICE_NO, ''\s'', ''''), ''[^,]+'', 1, LEVEL)) AS p_agr_nbr',
'          FROM dual',
'         WHERE REGEXP_LIKE(RTRIM(REGEXP_REPLACE(:P2110_LICE_NO, ''\s'', ''''), '',''), ''^[0-9]+(,[0-9]+)*$'')',
'       CONNECT BY REGEXP_SUBSTR(REGEXP_REPLACE(:P2110_LICE_NO, ''\s'', ''''), ''[^,]+'', 1, LEVEL) IS NOT NULL) l,',
'       importers i',
' WHERE i.impr_nbr (+) = l.p_agr_nbr',
'   AND i.port_cd (+) = NVL(:P2110_P_PORT_CD, :P_CURR_PORT_CD)',
' ORDER BY l.seq'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P2110_LICE_NO,P2110_P_PORT_CD'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
,p_plug_comment=>'Source: IMPR2110.CTR_BLK (control block, 5 records, read only: the numbers of LICE_NO and their names) / spec 3'
);
