'-- (CALLING_PARAMETERS.LICE_NO.WHEN-VALIDATE-ITEM: port NVL(P_PORT_CD, PARAMETER.P_CURR_PORT_CD), message if not found)',
'SELECT l.seq, l.p_agr_nbr,',
unistr('       NVL(i.arbc_impr_name, ''\0647\0630\0627 \0627\0644\0645\0633\062A\0648\0631\062F \063A\064A\0631 \0645\0648\062C\0648\062F'') AS p_agr_desc'),
'  FROM (SELECT LEVEL AS seq,',
'               TO_NUMBER(REGEXP_SUBSTR(REGEXP_REPLACE(:P2130_LICE_NO, ''\s'', ''''), ''[^,]+'', 1, LEVEL)) AS p_agr_nbr',
'          FROM dual',
'         WHERE REGEXP_LIKE(RTRIM(REGEXP_REPLACE(:P2130_LICE_NO, ''\s'', ''''), '',''), ''^[0-9]+(,[0-9]+)*$'')',
'       CONNECT BY REGEXP_SUBSTR(REGEXP_REPLACE(:P2130_LICE_NO, ''\s'', ''''), ''[^,]+'', 1, LEVEL) IS NOT NULL) l,',
'       importers i',
' WHERE i.impr_nbr (+) = l.p_agr_nbr',
'   AND i.port_cd (+) = NVL(:P2130_P_PORT_CD, :P_CURR_PORT_CD)',
' ORDER BY l.seq'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P2130_LICE_NO,P2130_P_PORT_CD'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
,p_plug_comment=>'Source: IMPR2130.CTR_BLK (control block, 5 records, read only: the numbers of LICE_NO and their names) / spec 3'
);
